#!/usr/bin/env bash
# GENERATED by plugin-cursor/scripts/compose.sh — edit plugin/ then re-compose
# Export plugin metadata as env vars for any hook that sources this file.
#
# Usage:
#   source "${PLUGIN_ROOT}/hooks/_plugin-env.sh"
#
# Sets:
#   SYNAPTORY_PLUGIN_VERSION  — read from .cursor-plugin/plugin.json. Picked up
#                          by the CLI (cli/internal/cli/root.go) and sent
#                          to the API as X-Synaptory-Plugin-Version (ADR-018).
#                          Empty if plugin.json is missing or malformed.
#   SYNAPTORY_ACTIVE_SPEC     — read from $CLAUDE_PROJECT_DIR/.synaptory/.orchestrator/
#                          pipeline-state.json `active_spec` when the project is
#                          in multi-spec mode (v3.0 schema). Empty for v2.0
#                          single-spec projects. Consumed by:
#                            - synaptory-verify-receipt.sh — selects per-spec
#                              .synaptory/.orchestrator/specs/<id>/receipts/
#                              directory instead of the flat legacy path.
#                            - scrum/kanban state-machine Python libs.
#                          Without this export, every hook in a multi-spec
#                          project reads the legacy flat dir, finds no
#                          receipts, falls into transcript recovery, and
#                          emits spurious receipt_invalid spans.
#
# Idempotent: safe to source multiple times in the same shell.

if [[ -z "${SYNAPTORY_PLUGIN_VERSION:-}" ]]; then
  _root="${PLUGIN_ROOT:-${_HOOK_ROOT:-${PLUGIN_ROOT:-}}}"
  if [[ -z "$_root" ]]; then return 0 2>/dev/null || exit 0; fi
  _plugin_json="${_root}/.cursor-plugin/plugin.json"
  if [[ -r "$_plugin_json" ]]; then
    # Pure-bash extraction — no jq dependency. Matches:
    #   "version": "2.5.26"
    SYNAPTORY_PLUGIN_VERSION=$(
      sed -n 's/.*"version"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "$_plugin_json" \
        | head -n1
    )
    export SYNAPTORY_PLUGIN_VERSION
  fi
  unset _plugin_json _root
fi

# SYNAPTORY_ACTIVE_SPEC: resolve from pipeline-state.json when not already set.
# Pure-bash JSON extraction kept narrow — matches the canonical v3 shape
# `"active_spec": "<id>"`. Treats v2 single-spec projects as empty (no
# multi-spec routing).
if [[ -z "${SYNAPTORY_ACTIVE_SPEC:-}" ]] && [[ -n "${CLAUDE_PROJECT_DIR:-}" ]]; then
  _state="${CLAUDE_PROJECT_DIR}/.synaptory/.orchestrator/pipeline-state.json"
  if [[ -r "$_state" ]]; then
    SYNAPTORY_ACTIVE_SPEC=$(
      sed -n 's/.*"active_spec"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "$_state" \
        | head -n1
    )
    if [[ -n "$SYNAPTORY_ACTIVE_SPEC" ]]; then
      export SYNAPTORY_ACTIVE_SPEC
    fi
  fi
  unset _state
fi
